import java.util.*;

class MyStack {
    private Queue<Integer> q = new ArrayDeque<>();

    public MyStack() {
    }

    public void push(int x) {
        q.add(x);
        for (int i = 1; i < q.size(); i++) q.add(q.remove()); // bring x to the front
    }

    public int pop() {
        return q.remove();
    }

    public int top() {
        return q.peek();
    }

    public boolean empty() {
        return q.isEmpty();
    }
}

